// jsdom pin: this suite needs window.confirm stub (happy-dom differs); keep on jsdom.
// @vitest-environment jsdom
import { expect, test, vi, beforeEach } from 'vitest';
import { screen, fireEvent, waitFor, within } from '@testing-library/react';
import { renderWithKainBain } from '../../testUtils';
import { NowPlayingBar, resolveRunnerBoxes, runnerBoxHealth } from './NowPlayingBar';
import { KainBainContext } from '../../context/KainBainContext';
import React from 'react';
import '@testing-library/jest-dom';

// The bar polls GET /runners/monitor for live assignments when the context
// carries no `runnerAssignments` override. Pin that poll to empty here so
// tests never depend on a real backend (a live fleet would otherwise flip
// the legacy-display assertions to runner boxes mid-suite). The build-hash
// trigger polls /status and /deploy/changelog the same way: default to an
// unbaked build so existing tests see no trigger unless they opt in.
vi.mock('../../services/api', () => ({
  api: {
    getRunnerMonitor: vi.fn(async () => ({ liveAssignments: [] })),
    systemStatus: vi.fn(async () => ({ build: null })),
    deployChangelog: vi.fn(async () => ({ changelog: null, reason: 'not-baked' })),
    observabilityStatus: vi.fn(async () => ({ observability: { queue: [] } })),
  },
}));

import { api } from '../../services/api';

// Default the polled backends to empty every test so the build-hash trigger
// (unbaked build) and runner roster (no fleet) stay out of the way unless a
// test opts in with its own mockResolvedValue. The queue popup fetches the
// global dispatch queue on open only; default it to empty for the same reason.
beforeEach(() => {
  api.getRunnerMonitor.mockResolvedValue({ liveAssignments: [] });
  api.systemStatus.mockResolvedValue({ build: null });
  api.deployChangelog.mockResolvedValue({ changelog: null, reason: 'not-baked' });
  api.observabilityStatus.mockResolvedValue({ observability: { queue: [] } });
});

/***
 * MARK: NowPlayingBar tests
 * @description Verifies the Now Playing bar: current task display, the
 * always-on runner boxes (fleet roster with per-runner play/pause + skip,
 * idle boxes included), global engine status badge
 * (IDLE, RUNNING, CHECKPOINT, PAUSED), the live queue-depth chip (the only
 * right-rail content), and the absence of any fabricated percentage bar,
 * stale stage-position label, elapsed timer, subsystem health light, or
 * global transport cluster.
 ***/
const stages = [
  { id: '1', name: 'Idea', type: 'agent' },
  { id: '2', name: 'Review', type: 'human' },
  { id: '3', name: 'In Progress', type: 'agent' },
];

test('renders live queue chip with no stale stage label (no fake progress bar, timer, or health light)', () => {
  renderWithKainBain(<NowPlayingBar />, {
    stages,
    currentStageId: '2',
    workflows: [],
    tasks: [
      { id: 't1', currentStageId: '2', status: 'in_stage' },
      { id: 't2', currentStageId: '1', status: 'in_stage' },
      { id: 't3', currentStageId: '1', status: 'completed' },
    ],
    isAgentRunning: false,
  });
  // The stale workflow-pointer stage label ("Stage 1 of 10 — Idea") is gone
  // for good: it was derived from currentStageId, which the workflow only sets
  // on initial fetch or manual skip, so it never updated. Guard against its
  // return even though stages are loaded and a stage is focused.
  expect(screen.queryByText(/Stage \d+ of \d+/)).not.toBeInTheDocument();
  expect(screen.queryByText(/— Idea/)).not.toBeInTheDocument();
  // The right rail is queue-only: the live queue-depth chip counts open tasks
  // only — t1 and t2 are open, t3 is completed and excluded.
  expect(
    screen.getByRole('button', {
      name: 'Execution queue: 2 open tasks across all pipelines',
    }),
  ).toHaveTextContent('2');
  // The elapsed timer and the subsystem health light were removed with the
  // right-rail trim: guard against either coming back.
  expect(screen.queryByLabelText('Elapsed time in current stage')).not.toBeInTheDocument();
  expect(screen.queryByText('Elapsed')).not.toBeInTheDocument();
  expect(screen.queryByRole('status', { name: /Subsystem Health/i })).not.toBeInTheDocument();
  expect(screen.queryByTestId('traffic-dot-litellm')).not.toBeInTheDocument();
  // No fabricated percentage bar. The stack has no
  // percent-complete data, so a percentage would be stage position masquerading
  // as progress — guard against it ever coming back.
  expect(screen.queryByRole('progressbar')).not.toBeInTheDocument();
  expect(screen.queryByText(/%/)).not.toBeInTheDocument();
});

test('queue chip is live: count updates as tasks advance and drops to zero when all complete', () => {
